},
"Authority": {
"Explanation": "The email uses authority by claiming that the sender is an operational manager in an account management section of a prime bank in South Africa. This may establish credibility and increase the recipient's trust in the sender."
},
"Commitment/Consistency": {
"Explanation": "The email references the sender's prior behavior of discussing the issue with the bank manager and watching for the next of kin to claim the funds. This creates a sense of commitment and consistency and may increase the recipient's belief in the legitimacy of the proposal."
},
"Liking": {
"Explanation": "The email does not explicitly use the liking principle, but it may attempt to build rapport by promising to set aside a portion of the funds for charity in the recipient's country."
},
"Social proof": {
"Explanation": "The email does not explicitly use social proof, but it does mention that the sender has discussed the issue with the bank manager and that the transfer of funds requires the involvement of the bank manager."
}
}

